    {
      "name": "Fire",
      "description": "butane lighter or matches, or other fire making device; stove in areas where no firewood will be available"
    },
    {
      "name": "Shelter",
      "description": "plastic tube tent, jumbo plastic trash bag or bivy sack"
    },
    {
      "name": "Extra food",
